import React from 'react';

import kframe from '../assets/kframe.png';
import walid from '../assets/walid.png';



function Projects() {
  return (
    <section className="projects-grid container">
      <h2>Featured Projects</h2>

      <div className="project-card">
        <div className="project-image">
          <img src={kframe} alt="KFrame Project" />
          <img src={walid} alt="Walid Project" />
          <img src={kframe} alt="KFrame Project" />
          <img src={walid} alt="Walid Project" />
        </div>
        <h3>KFrame & Walid Projects</h3>
      </div>

    </section>
  );
}

export default Projects;
